#import "SLReaderViewController.h"
#import "SLStore.h"
#import "SLAPI.h"
#import "SLDownloadManager.h"
#import <ImageIO/ImageIO.h>
@implementation SLReaderViewController
- (id)initWithSlug:(NSString *)slug chapter:(NSDictionary *)chapter {return [self initWithSlug:slug chapter:chapter titleInfo:nil];}
- (id)initWithSlug:(NSString *)slug chapter:(NSDictionary *)chapter titleInfo:(NSDictionary *)titleInfo { if((self=[super init])){_slug=[slug copy];_chapter=[chapter copy];_titleInfo=[titleInfo copy];_images=[[NSMutableArray alloc]init];_pageData=[[NSMutableArray alloc]init];_imageQueue=[[NSOperationQueue alloc]init];_imageQueue.maxConcurrentOperationCount=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLEnergySaving"]?1:2;_paged=([[NSUserDefaults standardUserDefaults]integerForKey:@"SLReadMode"]!=0);self.title=[NSString stringWithFormat:@"Глава %@",[chapter objectForKey:@"number"]?:@"?"];}return self; }
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];[UIApplication sharedApplication].idleTimerDisabled=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLKeepAwake"]; }
- (void)viewWillDisappear:(BOOL)animated{[super viewWillDisappear:animated];[UIApplication sharedApplication].idleTimerDisabled=NO;}
- (void)viewDidLoad { [super viewDidLoad]; NSInteger bg=[[NSUserDefaults standardUserDefaults]integerForKey:@"SLPageBackground"];UIColor *pageBG=bg==1?[UIColor colorWithWhite:0.35 alpha:1]:(bg==2?[UIColor whiteColor]:[UIColor blackColor]);self.view.backgroundColor=pageBG;_scroll=[[UIScrollView alloc]initWithFrame:self.view.bounds];_scroll.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;_scroll.delegate=self;_scroll.backgroundColor=pageBG;_scroll.pagingEnabled=_paged;_scroll.showsHorizontalScrollIndicator=NO;_scroll.showsVerticalScrollIndicator=NO;[self.view addSubview:_scroll];_spinner=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleWhiteLarge];_spinner.center=CGPointMake(self.view.bounds.size.width/2,self.view.bounds.size.height/2);_spinner.autoresizingMask=UIViewAutoresizingFlexibleLeftMargin|UIViewAutoresizingFlexibleRightMargin|UIViewAutoresizingFlexibleTopMargin|UIViewAutoresizingFlexibleBottomMargin;[_spinner startAnimating];[self.view addSubview:_spinner];UIBarButtonItem *mode=[[[UIBarButtonItem alloc]initWithTitle:_paged?@"Лента":@"Страницы" style:UIBarButtonItemStylePlain target:self action:@selector(toggleMode)]autorelease];UIBarButtonItem *bookmark=[[[UIBarButtonItem alloc]initWithTitle:[SLStore isBookmarked:_slug chapterID:[_chapter objectForKey:@"id"]]?@"★":@"☆" style:UIBarButtonItemStylePlain target:self action:@selector(toggleBookmark)]autorelease];self.navigationItem.rightBarButtonItems=[NSArray arrayWithObjects:mode,bookmark,nil];[self loadPages]; }
- (void)toggleMode{_paged=!_paged;[[NSUserDefaults standardUserDefaults]setInteger:_paged?1:0 forKey:@"SLReadMode"];self.navigationItem.rightBarButtonItem.title=_paged?@"Лента":@"Страницы";_scroll.pagingEnabled=_paged;[self layoutPages];}
- (void)loadPages {
    _restorePage=[[_chapter objectForKey:@"_startPage"]integerValue];
    if(![_chapter objectForKey:@"_startPage"]){for(NSDictionary *recent in [SLStore array:@"SLHistory"]){NSString *recentSlug=[recent objectForKey:@"slug_url"]?:[recent objectForKey:@"slug"];if([recentSlug isEqualToString:_slug]){NSDictionary *last=[recent objectForKey:@"_lastChapter"];if([[[last objectForKey:@"id"]description]isEqualToString:[[_chapter objectForKey:@"id"]description]])_restorePage=[[recent objectForKey:@"_lastPage"]integerValue];break;}}}
    NSDictionary *offline=[[SLDownloadManager shared]downloadedChapterForSlug:_slug chapterID:[_chapter objectForKey:@"id"]?:@"0"];
    if(offline){NSArray *names=[offline objectForKey:@"pages"];NSString *dir=[offline objectForKey:@"path"];for(NSString *name in names){NSString *path=[dir stringByAppendingPathComponent:name];if([[NSFileManager defaultManager]fileExistsAtPath:path])[_pageData addObject:[NSDictionary dictionaryWithObject:path forKey:@"localPath"]];}if([_pageData count]){[self showPageData];return;}}
    [[SLAPI shared]pages:_slug chapter:_chapter site:[[_chapter objectForKey:@"site"]integerValue] completion:^(id root,NSError *err){NSArray *pages=[[root objectForKey:@"data"]objectForKey:@"pages"];if(err||![pages isKindOfClass:[NSArray class]]||![pages count]){dispatch_async(dispatch_get_main_queue(),^{[_spinner stopAnimating];[self showError:err?[err localizedDescription]:@"Страницы не найдены"];});return;}[_pageData addObjectsFromArray:pages];[self showPageData];}];
}
- (void)showPageData { dispatch_async(dispatch_get_main_queue(),^{[_spinner stopAnimating];UIColor *pageBG=_scroll.backgroundColor;NSArray *data=_pageData;if(_paged&&[[NSUserDefaults standardUserDefaults]boolForKey:@"SLReadRTL"])data=[[_pageData reverseObjectEnumerator]allObjects];CGFloat w=self.view.bounds.size.width;CGFloat y=0;NSUInteger i=0;for(NSDictionary *p in data){UIImageView *iv=[[[UIImageView alloc]initWithFrame:CGRectMake(_paged?i*w:0,_paged?0:y,w,_paged?self.view.bounds.size.height:w*1.45)]autorelease];iv.contentMode=UIViewContentModeScaleAspectFit;iv.backgroundColor=pageBG;iv.tag=i;[_scroll addSubview:iv];[_images addObject:iv];NSString *local=[p objectForKey:@"localPath"];if(local){NSData *localData=[NSData dataWithContentsOfFile:local];UIImage *im=[self imageFromData:localData];if(im){iv.image=im;if(!_paged){CGRect f=iv.frame;f.size.height=im.size.height*(w/im.size.width);iv.frame=f;}}}else{NSString *url=[p objectForKey:@"url"];if(![url isKindOfClass:[NSString class]]){i++;continue;}if([url rangeOfString:@"http"].location!=0)url=[@"https:" stringByAppendingString:url];NSURLRequest *req=[NSURLRequest requestWithURL:[NSURL URLWithString:url] cachePolicy:NSURLRequestReturnCacheDataElseLoad timeoutInterval:90];[NSURLConnection sendAsynchronousRequest:req queue:_imageQueue completionHandler:^(NSURLResponse *r,NSData *d,NSError *e){UIImage *im=d?[self imageFromData:d]:nil;if(im)dispatch_async(dispatch_get_main_queue(),^{iv.image=im;if(!_paged){CGRect f=iv.frame;f.size.height=im.size.height*(w/im.size.width);iv.frame=f;[self recalculateVerticalContent];}});}];}if(!_paged)y+=iv.frame.size.height;i++;}
        if(_paged)_scroll.contentSize=CGSizeMake(w*[_images count],self.view.bounds.size.height);else{_scroll.contentSize=CGSizeMake(w,y);}if(_restorePage>=(NSInteger)[_images count])_restorePage=(NSInteger)[_images count]-1;if(_restorePage<0)_restorePage=0;if(_paged)_scroll.contentOffset=CGPointMake(w*_restorePage,0);else{CGFloat targetY=0;for(NSInteger z=0;z<_restorePage&&z<(NSInteger)[_images count];z++)targetY+=((UIImageView *)[_images objectAtIndex:z]).frame.size.height;_scroll.contentOffset=CGPointMake(0,targetY);}if([_pageData count]){[SLStore markRead:_slug chapter:[_chapter objectForKey:@"id"]?:@"0"];[self saveProgress:(NSUInteger)_restorePage];}if(![_images count])[self showError:@"Не удалось открыть страницы"];});}
- (void)recalculateVerticalContent{CGFloat y=0;for(UIView *v in _images){CGRect f=v.frame;f.origin.y=y;v.frame=f;y+=f.size.height;} _scroll.contentSize=CGSizeMake(self.view.bounds.size.width,y);}
- (void)layoutPages{CGFloat w=self.view.bounds.size.width,h=self.view.bounds.size.height;NSUInteger i=0;CGFloat y=0;for(UIImageView *iv in _images){UIImage *im=iv.image;CGFloat ih=im?im.size.height*(w/im.size.width):w*1.45;iv.frame=CGRectMake(_paged?i*w:0,_paged?0:y,w,_paged?h:ih);if(!_paged)y+=ih;i++;} _scroll.contentSize=_paged?CGSizeMake(w*[_images count],h):CGSizeMake(w,y);}
- (void)scrollViewDidEndDecelerating:(UIScrollView *)scrollView{NSUInteger page=_paged?(NSUInteger)(scrollView.contentOffset.x/MAX(scrollView.bounds.size.width,1)):[self visibleVerticalPage];[self saveProgress:page];}
- (NSUInteger)visibleVerticalPage{CGFloat y=_scroll.contentOffset.y;NSUInteger idx=0;for(UIImageView *iv in _images){if(CGRectGetMaxY(iv.frame)>y){return idx;}idx++;}return idx?idx-1:0;}
- (void)saveProgress:(NSUInteger)page {if(page>=[_pageData count])page=[_pageData count]?[_pageData count]-1:0;NSDictionary *title=_titleInfo?:[NSDictionary dictionaryWithObjectsAndKeys:_slug,@"slug_url",_slug,@"slug",nil];[SLStore updateRecent:title chapter:_chapter page:page pageCount:[_pageData count]];}
- (void)toggleBookmark {id chapterID=[_chapter objectForKey:@"id"]?:@"0";if([SLStore isBookmarked:_slug chapterID:chapterID])[SLStore removeBookmark:_slug chapterID:chapterID];else{NSMutableArray *branchIDs=[NSMutableArray array];for(NSDictionary *branch in [_chapter objectForKey:@"branches"]?:[NSArray array]){id bid=[branch objectForKey:@"branch_id"];if(bid)[branchIDs addObject:bid];}if(![branchIDs count]&&[_chapter objectForKey:@"branchIds"])[branchIDs addObjectsFromArray:[_chapter objectForKey:@"branchIds"]];NSMutableDictionary *b=[NSMutableDictionary dictionaryWithObjectsAndKeys:_slug,@"slug",chapterID,@"chapterId",[_chapter objectForKey:@"volume"]?:@"0",@"volume",[_chapter objectForKey:@"number"]?:@"0",@"number",[_chapter objectForKey:@"name"]?:@"",@"chapterName",branchIDs,@"branchIds",[NSNumber numberWithUnsignedInteger:_paged?(NSUInteger)(_scroll.contentOffset.x/MAX(_scroll.bounds.size.width,1)):[self visibleVerticalPage]],@"page",[NSNumber numberWithUnsignedInteger:[_pageData count]],@"pageCount",[NSNumber numberWithDouble:[[NSDate date]timeIntervalSince1970]],@"date",[_chapter objectForKey:@"site"]?:@2,@"site",nil];if(_titleInfo)[b setObject:_titleInfo forKey:@"titleInfo"];[SLStore saveBookmark:b];}((UIBarButtonItem *)[self.navigationItem.rightBarButtonItems lastObject]).title=[SLStore isBookmarked:_slug chapterID:chapterID]?@"★":@"☆";}
- (UIImage *)imageFromData:(NSData *)data { if(!data)return nil;CGImageSourceRef source=CGImageSourceCreateWithData((CFDataRef)data,NULL);if(!source)return [UIImage imageWithData:data];CGFloat px=MAX(self.view.bounds.size.width,self.view.bounds.size.height)*2.0;NSUInteger cap=[[NSUserDefaults standardUserDefaults]boolForKey:@"SLEnergySaving"]?1100:1600;NSDictionary *options=[NSDictionary dictionaryWithObjectsAndKeys:(id)kCFBooleanTrue,(id)kCGImageSourceCreateThumbnailFromImageAlways,[NSNumber numberWithUnsignedInteger:MIN((NSUInteger)px,cap)],(id)kCGImageSourceThumbnailMaxPixelSize,(id)kCFBooleanTrue,(id)kCGImageSourceShouldCache,nil];CGImageRef cg=CGImageSourceCreateThumbnailAtIndex(source,0,(CFDictionaryRef)options);CFRelease(source);if(!cg)return [UIImage imageWithData:data];UIImage *image=[UIImage imageWithCGImage:cg];CGImageRelease(cg);return image;}
- (void)showError:(NSString *)message{UILabel *l=[[[UILabel alloc]initWithFrame:self.view.bounds]autorelease];l.text=message;l.textColor=[UIColor whiteColor];l.textAlignment=UITextAlignmentCenter;l.numberOfLines=3;l.autoresizingMask=UIViewAutoresizingFlexibleWidth|UIViewAutoresizingFlexibleHeight;[self.view addSubview:l];}
- (void)dealloc{[_slug release];[_chapter release];[_titleInfo release];[_scroll release];[_spinner release];[_images release];[_pageData release];[_imageQueue cancelAllOperations];[_imageQueue release];[super dealloc];}
@end
